import{_ as a,o,c as t,a2 as r}from"./chunks/framework.YT-FC_Xx.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1793327746000}'),l={name:"guide/faq.md"};function i(d,e,n,s,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>想先看看面板长什么样，可以打开 <a href="https://kure29.github.io/flyx/demo/" target="_blank" rel="noreferrer">在线演示</a>。这里没找到答案的话，可以到 <a href="https://t.me/flyx_chat" target="_blank" rel="noreferrer">Telegram 交流群</a> 问，或者在 GitHub <a href="https://github.com/kure29/flyx/issues/new/choose" target="_blank" rel="noreferrer">提交 issue</a>。</p><h2 id="面板" tabindex="-1">面板 <a class="header-anchor" href="#面板" aria-label="Permalink to &quot;面板&quot;">​</a></h2><h3 id="whmcs-等集成登录提示-验证码校验失败" tabindex="-1">WHMCS 等集成登录提示“验证码校验失败”？ <a class="header-anchor" href="#whmcs-等集成登录提示-验证码校验失败" aria-label="Permalink to &quot;WHMCS 等集成登录提示“验证码校验失败”？&quot;">​</a></h3><p>启用登录验证码并配置完整的 Cloudflare Turnstile 密钥后，所有密码登录都必须提交有效的 <code>captchaId</code>，包括 WHMCS 等集成。<code>X-FLVX-API-Client</code> 是客户端可自行填写的请求头，不再提供验证码豁免。依赖旧豁免的集成需要适配验证码流程；验证码令牌只能使用一次。</p><h3 id="安装脚本提示-docker-command-not-found" tabindex="-1">安装脚本提示 &quot;Docker command not found&quot;？ <a class="header-anchor" href="#安装脚本提示-docker-command-not-found" aria-label="Permalink to &quot;安装脚本提示 &quot;Docker command not found&quot;？&quot;">​</a></h3><p>请确保您的系统已安装 Docker 和 Docker Compose。</p><ul><li>Ubuntu/Debian 安装 Docker: <code>curl -fsSL https://get.docker.com | bash</code></li></ul><h3 id="面板无法访问-connection-refused" tabindex="-1">面板无法访问 (Connection Refused)？ <a class="header-anchor" href="#面板无法访问-connection-refused" aria-label="Permalink to &quot;面板无法访问 (Connection Refused)？&quot;">​</a></h3><ol><li>检查防火墙是否放行了前端端口（默认 <code>6366</code>）。</li><li>检查容器是否正常运行: <code>docker ps</code>。</li><li>查看容器日志: <code>docker logs flux-panel-backend</code> 或 <code>docker logs vite-frontend</code>。</li></ol><h3 id="用-ip-访问时复制失败" tabindex="-1">用 IP 访问时复制失败 <a class="header-anchor" href="#用-ip-访问时复制失败" aria-label="Permalink to &quot;用 IP 访问时复制失败&quot;">​</a></h3><p>浏览器只在 HTTPS 页面里完全开放复制功能。面板会自动改用兼容方式复制，仍失败时会提示；建议通过 HTTPS 域名访问面板，或长按文字手动复制。</p><h3 id="面板自升级提示-部署docker-compose-yml不可用" tabindex="-1">面板自升级提示“部署docker-compose.yml不可用” <a class="header-anchor" href="#面板自升级提示-部署docker-compose-yml不可用" aria-label="Permalink to &quot;面板自升级提示“部署docker-compose.yml不可用”&quot;">​</a></h3><p>见 <a href="./upgrade#修复面板内升级">升级</a>。</p><h3 id="ipv6-无法使用" tabindex="-1">IPv6 无法使用？ <a class="header-anchor" href="#ipv6-无法使用" aria-label="Permalink to &quot;IPv6 无法使用？&quot;">​</a></h3><p>面板安装脚本会自动尝试配置 Docker 的 IPv6。如果失败，请手动检查 <code>/etc/docker/daemon.json</code> 配置，确保 <code>ipv6: true</code> 且分配了正确的 <code>fixed-cidr-v6</code> 子网。</p><h2 id="agent" tabindex="-1">agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;agent&quot;">​</a></h2><h3 id="服务器显示离线" tabindex="-1">服务器显示离线？ <a class="header-anchor" href="#服务器显示离线" aria-label="Permalink to &quot;服务器显示离线？&quot;">​</a></h3><ol><li>检查服务器与面板服务器之间的网络连通性。</li><li>确认在服务器端安装时输入的 <strong>面板地址</strong> 和 <strong>密钥</strong> 是否正确。</li><li>检查服务器端服务状态：<code>systemctl status flyx-agent</code>（Alpine 用 <code>rc-service flyx-agent status</code>；3.4.0 之前安装的节点是 <code>flux_agent</code>）。</li><li>查看服务器端日志：<code>journalctl -u flyx-agent -f</code>。</li></ol><h3 id="部署或升级服务器提示-api-rate-limit-exceeded" tabindex="-1">部署或升级服务器提示 “API rate limit exceeded”？ <a class="header-anchor" href="#部署或升级服务器提示-api-rate-limit-exceeded" aria-label="Permalink to &quot;部署或升级服务器提示 “API rate limit exceeded”？&quot;">​</a></h3><p>面板要向 GitHub 查询最新版本号。不登录的查询每个 IP 每小时只有 60 次，VPS 的 IP 常常和别人共用，可能早就被用完。面板会把查询结果缓存 10 分钟，查询失败时用上次的结果，正式版还会改用不受这个限制的方式查询，所以一般不会再遇到。</p><p>测试版或面板刚启动时仍可能出现，等一小时再试，或者给面板配一个 GitHub token：在 GitHub 的 Settings → Developer settings → Personal access tokens 新建一个 fine-grained token（只需公开仓库只读，不用勾任何权限），写进部署目录的 <code>.env</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GITHUB_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">github_pat_xxx</span></span></code></pre></div><p>然后 <code>docker compose up -d</code> 重建后端，限额变为每小时 5000 次。旧版 <code>docker-compose.yml</code> 需要在 <code>backend.environment</code> 里加上 <code>GITHUB_TOKEN: ${GITHUB_TOKEN:-}</code>。</p><h3 id="只有-tcp-能通-udp-不通" tabindex="-1">只有 TCP 能通，UDP 不通？ <a class="header-anchor" href="#只有-tcp-能通-udp-不通" aria-label="Permalink to &quot;只有 TCP 能通，UDP 不通？&quot;">​</a></h3><p>请检查服务器防火墙和安全组（AWS/阿里云/腾讯云等）是否同时放行了对应端口的 <strong>TCP 和 UDP</strong> 协议。</p><h2 id="内核与入站" tabindex="-1">内核与入站 <a class="header-anchor" href="#内核与入站" aria-label="Permalink to &quot;内核与入站&quot;">​</a></h2><h3 id="内核状态显示-异常" tabindex="-1">内核状态显示“异常” <a class="header-anchor" href="#内核状态显示-异常" aria-label="Permalink to &quot;内核状态显示“异常”&quot;">​</a></h3><p>在“内核”标签里点击该内核 → “日志”查看原因，常见的有端口被占用、证书路径不存在、IPv6 被禁用（见 <a href="./nodes#监听地址">新建入站 - 监听地址</a>）。</p><h3 id="snell-用哪个版本、哪个内核" tabindex="-1">Snell 用哪个版本、哪个内核 <a class="header-anchor" href="#snell-用哪个版本、哪个内核" aria-label="Permalink to &quot;Snell 用哪个版本、哪个内核&quot;">​</a></h3><p>有两种：Snell 内核（官方 snell-server：5.x 支持 v4 / v5，含 v5 的 QUIC 代理模式；6.0.0 测试版只支持 v6）和 sing-box 1.14 起内置的 Snell（支持 v4 / v5 / v6、分流和链式出站，不支持 QUIC 模式）。对比和选择见 <a href="./kernels#snell-用哪个内核">Snell 用哪个内核</a>。</p><p>用 Snell 内核时，入站的 Snell 版本要和服务器安装的版本对得上：v5 入站需要 Snell 5.x，v6 入站需要 Snell 6.0.0（测试版，只接受 v6 客户端）。</p><h3 id="sing-box-提示需要-1-14-及以上" tabindex="-1">sing-box 提示需要 1.14 及以上 <a class="header-anchor" href="#sing-box-提示需要-1-14-及以上" aria-label="Permalink to &quot;sing-box 提示需要 1.14 及以上&quot;">​</a></h3><p>自动申请证书（ACME）和内置 Snell 是 sing-box 1.14 才有的功能。在 <strong>服务器 → 内核</strong> 点该 sing-box → 更换版本，选最新版即可。已经有这类入站时，也不能把 sing-box 换回 1.14 以前的版本。</p><h3 id="acme-一直申请不到证书" tabindex="-1">ACME 一直申请不到证书 <a class="header-anchor" href="#acme-一直申请不到证书" aria-label="Permalink to &quot;ACME 一直申请不到证书&quot;">​</a></h3><p>确认域名已解析到服务器；HTTP 验证时 80 端口不能被其他程序占用，并且要能从公网访问；也可以改用 DNS 验证。</p><h3 id="reality-用-clash-mihomo-连不上" tabindex="-1">Reality 用 Clash / Mihomo 连不上 <a class="header-anchor" href="#reality-用-clash-mihomo-连不上" aria-label="Permalink to &quot;Reality 用 Clash / Mihomo 连不上&quot;">​</a></h3><p>Xray 26.7.11 起，Reality 未设置“最低客户端版本”时默认只接受 26.3.27 及以上的客户端，而 Mihomo（Clash Verge、Stash、FlClash 等）上报的版本是 1.8.2，会被拒绝。面板默认把最低客户端版本设为 <code>1.0.0</code>，所有客户端都能连接；如需调整，在 Reality 设置里修改“最低客户端版本”。也可以在安装内核时选择旧版本的 Xray。</p><p>服务器装的是 Xray 25.5.16 及以上时，Mihomo 订阅里的 VLESS Reality 节点会带上 <code>support-x25519mlkem768: true</code>，启用抗量子的 X25519MLKEM768 密钥交换。这个选项需要服务端支持，所以 sing-box 内核、更旧的 Xray 和导入的节点都不会加；导入的节点保留订阅源本身的设置。</p><h2 id="订阅与流量" tabindex="-1">订阅与流量 <a class="header-anchor" href="#订阅与流量" aria-label="Permalink to &quot;订阅与流量&quot;">​</a></h2><h3 id="流量一直是-0" tabindex="-1">流量一直是 0 <a class="header-anchor" href="#流量一直是-0" aria-label="Permalink to &quot;流量一直是 0&quot;">​</a></h3><p>检查服务器是否安装了 nftables；流量每分钟左右同步一次。订阅流量还需要 agent 和面板一起更新到最新版，Shadowsocks、Snell 等共用凭据的入站不按订阅计数，见 <a href="./subscription-users#流量上限">凭据、到期与流量</a>。</p><h3 id="某个客户端里少了几个节点" tabindex="-1">某个客户端里少了几个节点 <a class="header-anchor" href="#某个客户端里少了几个节点" aria-label="Permalink to &quot;某个客户端里少了几个节点&quot;">​</a></h3><p>客户端不支持的协议会自动略过，例如 Surge 没有 VLESS，Clash 没有 Snell，1.14 以前的 sing-box 客户端也拿不到 Snell（升级客户端后重新更新订阅即可）。各格式不包含哪些协议见 <a href="./subscription#各格式不包含的协议">订阅与客户端</a>。</p><h2 id="延迟与回程" tabindex="-1">延迟与回程 <a class="header-anchor" href="#延迟与回程" aria-label="Permalink to &quot;延迟与回程&quot;">​</a></h2><h3 id="节点卡片上的延迟是从哪里测的" tabindex="-1">节点卡片上的延迟是从哪里测的 <a class="header-anchor" href="#节点卡片上的延迟是从哪里测的" aria-label="Permalink to &quot;节点卡片上的延迟是从哪里测的&quot;">​</a></h3><p>设置了 <a href="./latency">延迟测试点</a> 时，是所在服务器到各测试点（各地运营商）的延迟；没设置时是面板服务器到入站的延迟，只能作为参考。导入的节点没有 agent，只有面板发起的连通性检测。</p><h3 id="回程提示-agent-版本过旧" tabindex="-1">回程提示“agent 版本过旧” <a class="header-anchor" href="#回程提示-agent-版本过旧" aria-label="Permalink to &quot;回程提示“agent 版本过旧”&quot;">​</a></h3><p>回程检测需要新版 agent。到 <strong>服务器</strong> 页把服务器升级到最新版，升级后面板会马上重新检测，不用等第二天。</p><h3 id="回程提示-没有-root-net-raw-权限" tabindex="-1">回程提示“没有 root / NET_RAW 权限” <a class="header-anchor" href="#回程提示-没有-root-net-raw-权限" aria-label="Permalink to &quot;回程提示“没有 root / NET_RAW 权限”&quot;">​</a></h3><p>路由追踪要发原始 ICMP 包，agent 需要以 root 运行，或者有 <code>CAP_NET_RAW</code> 权限。用面板生成的命令安装的 agent 默认是 root。</p><h3 id="回程显示-未识别" tabindex="-1">回程显示“未识别” <a class="header-anchor" href="#回程显示-未识别" aria-label="Permalink to &quot;回程显示“未识别”&quot;">​</a></h3><p>路由没有经过 CN2、163、9929、4837、CMI 这些骨干网（比如走的是普通 IX 或运营商没有回应），面板就认不出线路。点 <strong>回程</strong> 可以看每一跳的 IP。</p><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><h3 id="如何切换到-postgresql" tabindex="-1">如何切换到 PostgreSQL？ <a class="header-anchor" href="#如何切换到-postgresql" aria-label="Permalink to &quot;如何切换到 PostgreSQL？&quot;">​</a></h3><p>在 <code>.env</code> 文件中设置 <code>DB_TYPE=postgres</code>，并让 <code>DATABASE_URL</code> 与 <code>POSTGRES_*</code> 保持一致，然后执行 <code>docker compose up -d</code> 重启服务即可。使用安装脚本部署时，<code>POSTGRES_PASSWORD</code> 会自动随机生成并写入 <code>.env</code>。详见 <a href="./postgresql">PostgreSQL</a>。</p><h3 id="从-sqlite-迁移到-postgresql-后数据丢失" tabindex="-1">从 SQLite 迁移到 PostgreSQL 后数据丢失？ <a class="header-anchor" href="#从-sqlite-迁移到-postgresql-后数据丢失" aria-label="Permalink to &quot;从 SQLite 迁移到 PostgreSQL 后数据丢失？&quot;">​</a></h3><ol><li>确认迁移前已备份 SQLite 文件（<code>gost.db.bak</code>）。</li><li>确认 <code>pgloader</code> 命令执行成功，检查其输出是否有报错。</li><li>确认 <code>.env</code> 中 <code>DATABASE_URL</code> 的密码与 <code>POSTGRES_PASSWORD</code> 一致。</li><li>详细迁移步骤参考 <a href="./postgresql">PostgreSQL</a>。</li></ol><h3 id="postgresql-容器启动失败" tabindex="-1">PostgreSQL 容器启动失败？ <a class="header-anchor" href="#postgresql-容器启动失败" aria-label="Permalink to &quot;PostgreSQL 容器启动失败？&quot;">​</a></h3><ol><li>检查 <code>POSTGRES_PASSWORD</code> 是否已设置（不能为空）。</li><li>查看容器日志：<code>docker logs flux-panel-postgres</code>。</li><li>如果是首次启动后修改了密码，需要删除旧的数据卷重新初始化：<code>docker volume rm postgres_data</code>。</li></ol>',60)])])}const b=a(l,[["render",i]]);export{u as __pageData,b as default};
